import{_ as s,C as i,c as l,o as d,a3 as n,G as o,j as t,a as r}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Refunds","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/selling/refunds.md","filePath":"master/sales/point-of-sale/selling/refunds.md","lastUpdated":1792041590000}'),h={name:"master/sales/point-of-sale/selling/refunds.md"};function u(c,e,p,f,g,m){const a=i("ImagePopup");return d(),l("div",null,[e[0]||(e[0]=n('<h1 id="refunds" tabindex="-1">Refunds <a class="header-anchor" href="#refunds" aria-label="Permalink to &quot;Refunds&quot;">​</a></h1><p>A refund returns products from a paid order and gives the money back. You start it from the terminal&#39;s <strong>Orders</strong> page. Aureus creates a new order with negative amounts, so the original sale stays untouched and your totals stay correct.</p><blockquote><p><strong>In simple words:</strong> Find the old order, choose what comes back, click Refund, and pay the customer back.</p></blockquote><p>You can refund only orders that are already paid. You cannot refund an order that is still <strong>New</strong>.</p><h2 id="find-the-order" tabindex="-1">Find the order <a class="header-anchor" href="#find-the-order" aria-label="Permalink to &quot;Find the order&quot;">​</a></h2><ol><li>Click your initials at the top right of the terminal, then <strong>Orders</strong>.</li><li>Search by order, receipt or customer. Or use the status filter, which starts on <strong>All active orders</strong>.</li><li>Click the order in the list. Its lines show on the right.</li></ol>',6)),o(a,{src:"/images1/pos/refund_orders_list.png",alt:"Terminal Orders page with TNE/00002 for Tom Baker selected and its line Nova X5 Smartphone 128GB on the right"}),e[1]||(e[1]=n('<p>The list shows <strong>Date</strong>, <strong>Receipt number</strong>, <strong>Order number</strong>, <strong>Customer</strong>, <strong>Cashier</strong>, <strong>Tracking number</strong>, <strong>Total</strong> and <strong>Status</strong>.</p><h2 id="choose-what-to-refund" tabindex="-1">Choose what to refund <a class="header-anchor" href="#choose-what-to-refund" aria-label="Permalink to &quot;Choose what to refund&quot;">​</a></h2><ol><li>Click the line you want to return. The panel says &quot;Select the product(s) to refund and set the quantity&quot;.</li><li>Use the number pad to set the quantity. The line shows <strong>To refund</strong>.</li><li>Repeat for other lines.</li></ol>',3)),o(a,{src:"/images1/pos/refund_select_qty.png",alt:"Selected order line Nova X5 Smartphone with To refund 1.00 and the Refund button at the bottom"}),e[2]||(e[2]=t("p",null,[t("strong",null,"Example:"),r(" Tom Baker bought one Nova X5 Smartphone for 24,999 on order TNE/00002. He brings it back. Click the line and keep the quantity at 1.")],-1)),e[3]||(e[3]=t("p",null,[r("A line also shows what is still "),t("strong",null,"Refundable"),r(". You cannot return more than the customer bought, and a partial refund is fine. For example, refund one of two mice.")],-1)),e[4]||(e[4]=t("h2",{id:"create-the-refund",tabindex:"-1"},[r("Create the refund "),t("a",{class:"header-anchor",href:"#create-the-refund","aria-label":'Permalink to "Create the refund"'},"​")],-1)),e[5]||(e[5]=t("p",null,[r("Click "),t("strong",null,"Refund"),r(". The terminal opens a new order with the returned lines at negative quantity. The customer is the same as on the original order. The total is negative, for example -24,999.")],-1)),o(a,{src:"/images1/pos/refund_new_order.png",alt:"New refund order with Nova X5 Smartphone quantity -1 and a total of -24,999 for Tom Baker"}),e[6]||(e[6]=n('<h2 id="pay-the-refund" tabindex="-1">Pay the refund <a class="header-anchor" href="#pay-the-refund" aria-label="Permalink to &quot;Pay the refund&quot;">​</a></h2><ol><li>Click <strong>Payment</strong>.</li><li>Choose the method, for example <strong>Cash</strong>. The amount is the negative total.</li><li>Click <strong>Validate</strong>.</li></ol>',2)),o(a,{src:"/images1/pos/refund_payment_cash.png",alt:"Payment screen of the refund with Cash -24,999 and the Validate button"}),e[7]||(e[7]=t("p",null,[r("The receipt shows negative amounts: "),t("strong",null,"TOTAL"),r(" -24,999 and "),t("strong",null,"Cash"),r(" -24,999. Print it for the customer if you wish. Give the cash back from the drawer.")],-1)),o(a,{src:"/images1/pos/refund_receipt.png",alt:"Refund receipt with Nova X5 Smartphone -1, TOTAL -24,999 and Cash -24,999"}),e[8]||(e[8]=n('<h2 id="where-the-refund-appears" tabindex="-1">Where the refund appears <a class="header-anchor" href="#where-the-refund-appears" aria-label="Permalink to &quot;Where the refund appears&quot;">​</a></h2><p>In the <strong>Orders</strong> list the refund shows as its own row, &quot;TNE/00002 REFUND&quot;, with the status <strong>Paid</strong> and a negative total. In the back office open <code>Point of Sale → Orders → Orders</code> and use the <strong>Refunds</strong> tab. The session also counts the money you gave back, so the cash at closing still balances.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><ul><li><strong>Details:</strong> Shows the order details.</li><li><strong>Invoice:</strong> Creates an invoice for the selected order. See <a href="./invoice-a-pos-order.html">Invoice a POS order</a>.</li><li><strong>Print receipt:</strong> Prints the receipt of the selected order again.</li><li><strong>Refund:</strong> Creates the refund order.</li></ul><p>If the original order was invoiced, invoicing the refund produces a credit note for the customer. See <a href="./../../../finance/customer-invoices/credit-notes-and-refunds.html">Credit notes and refunds</a>.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Refund and pay in the same session when you can. The drawer then shows the cash movement clearly.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A refund only returns what the original order sold. To change a price, cancel before payment instead.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./pay-and-receipt.html">Pay and receipt</a></li><li><a href="./../orders-payments/orders.html">Orders</a></li><li><a href="./../sessions/close-session.html">Close a session</a></li></ul>',9))])}const b=s(h,[["render",u]]);export{_ as __pageData,b as default};
